import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const d="/images/agent-create-worldbook.webp",b=JSON.parse('{"title":"世界书","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/worldbook.md","filePath":"guide/agent/worldbook.md","lastUpdated":1789295632000}'),l={name:"guide/agent/worldbook.md"};function n(i,t,s,h,p,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="世界书" tabindex="-1">世界书 <a class="header-anchor" href="#世界书" aria-label="Permalink to &quot;世界书&quot;">​</a></h1><p>世界书是角色的<strong>背景知识库</strong>：世界观、地点、组织、人物关系、历史事件、专有名词都放在这里。它不会一次性塞给模型，而是<strong>按需注入</strong>——只有与当前对话相关的条目才被激活，在不撑爆上下文的前提下让角色「懂」自己的世界。</p><p><img src="'+d+'" alt="世界书"></p><h2 id="什么内容适合放世界书" tabindex="-1">什么内容适合放世界书 <a class="header-anchor" href="#什么内容适合放世界书" aria-label="Permalink to &quot;什么内容适合放世界书&quot;">​</a></h2><p>判断标准：「不需要每句话都出现，但命中时必须知道」。</p><p>适合：地点设定、组织架构、人物关系、道具、专有名词、剧情阶段、角色外观细节。</p><p>不适合：每轮都必须生效的核心行为规则（放<a href="/guide/agent/create#人设模型的说明书">人设</a>），一次性剧情（直接在对话里说）。</p><h2 id="条目字段" tabindex="-1">条目字段 <a class="header-anchor" href="#条目字段" aria-label="Permalink to &quot;条目字段&quot;">​</a></h2><p>每个条目包含：</p><ul><li><strong>标题</strong>：条目的名字。手动触发时用它（或条目 ID）。</li><li><strong>内容</strong>：具体的设定文字。</li><li><strong>关键词</strong>：触发该条目的词，用换行、英文逗号或中文逗号分隔。</li><li><strong>触发方式</strong>：见下。</li><li><strong>优先级</strong>：数值越大越优先注入。</li><li><strong>启用</strong>：开关，关闭后不参与注入。</li></ul><p>条目支持新增、复制、删除。</p><h2 id="三种触发方式" tabindex="-1">三种触发方式 <a class="header-anchor" href="#三种触发方式" aria-label="Permalink to &quot;三种触发方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>何时注入</th><th>适合</th></tr></thead><tbody><tr><td>关键词</td><td>用户消息中出现关键词时。中文按包含关系匹配，英文按单词边界匹配</td><td>地点、人物、组织、道具等日常会提到的设定</td></tr><tr><td>手动</td><td>只在消息里出现 <code>[[wb:条目标题]]</code> 或 <code>[[wb:条目ID]]</code> 时</td><td>隐藏设定、不想被误触发的剧透、作者控制的剧情阶段</td></tr><tr><td>常驻</td><td>每轮对话都参与注入候选</td><td>必须始终生效的核心世界规则（别放太多，会挤占窗口）</td></tr></tbody></table><h2 id="命中规则" tabindex="-1">命中规则 <a class="header-anchor" href="#命中规则" aria-label="Permalink to &quot;命中规则&quot;">​</a></h2><p>每轮对话最多注入 12 条：</p><ul><li>常驻最多 4 条</li><li>手动最多 4 条</li><li>关键词最多 8 条</li></ul><p>还有空位时，会按优先级从所有命中的条目里补齐。所以<strong>重要设定给高优先级</strong>，别让冷门条目挤掉关键信息。</p><h2 id="命中预览" tabindex="-1">命中预览 <a class="header-anchor" href="#命中预览" aria-label="Permalink to &quot;命中预览&quot;">​</a></h2><p>编辑页提供「命中预览」：输入一段测试消息，直接看到本轮实际会注入哪些条目（含触发来源、优先级、命中的关键词）。发布前用它调一遍，比上线后靠用户反馈发现「设定没生效」划算得多。</p><p>手动条目在预览旁有一键插入按钮，可以快速把 <code>[[wb:标题]]</code> 标记插进消息。</p><h2 id="与记忆的分工" tabindex="-1">与记忆的分工 <a class="header-anchor" href="#与记忆的分工" aria-label="Permalink to &quot;与记忆的分工&quot;">​</a></h2><p>世界书是<strong>创作者写的、对所有用户一样</strong>的设定；<a href="/guide/agent/memory">记忆</a>是<strong>每个用户的会话里攒出来的</strong>经历。角色的世界观放世界书，用户在对话里聊出来的剧情细节，交给记忆。</p>',22)])])}const u=a(l,[["render",n]]);export{b as __pageData,u as default};
